import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()

    def parse_price(x):
        if pd.isna(x):
            return np.nan
        s = str(x).strip().replace('$', '').replace(',', '')
        try:
            return float(s)
        except ValueError:
            return np.nan

    df['Price'] = df['Price'].apply(parse_price)
    return df

def answer(df):
    result = {}
    grouped = df.groupby('Category')['Price'].mean()
    for category, value in grouped.items():
        if pd.isna(category):
            continue
        result[category] = float(value)
    return result
